<template><form @submit.prevent="submit"><div class="row g-3"><div class="col-md-6"><label class="form-label">Fecha y hora de actividad *</label><input v-model="form.fecha_actividad" type="datetime-local" class="form-control" required></div><div class="col-md-3"><label class="form-label">Presión sistólica *</label><input v-model.number="form.sv_pa_sistolica" type="number" min="1" class="form-control" required></div><div class="col-md-3"><label class="form-label">Presión diastólica *</label><input v-model.number="form.sv_pa_diastolica" type="number" min="1" class="form-control" required></div><div class="col-md-3"><label class="form-label">Frecuencia cardiaca *</label><input v-model.number="form.sv_frecuencia_cardiaca" type="number" min="1" class="form-control" required></div><div class="col-md-3"><label class="form-label">Frecuencia respiratoria *</label><input v-model.number="form.sv_frecuencia_respiratoria" type="number" min="1" class="form-control" required></div><div class="col-md-3"><label class="form-label">Temperatura °C *</label><input v-model.number="form.sv_temperatura" type="number" min="25" max="45" step="0.1" class="form-control" required></div><div class="col-md-3"><label class="form-label">Saturación %</label><input v-model.number="form.saturacion" type="number" min="0" max="100" class="form-control"></div><div class="col-md-4"><label class="form-label">Peso (kg)</label><input v-model.number="form.peso" type="number" min="0" step="0.1" class="form-control"></div><div class="col-md-4"><label class="form-label">Talla (cm)</label><input v-model.number="form.sv_talla" type="number" min="0" class="form-control"></div><div class="col-md-4"><label class="form-label">Circunferencia abdominal</label><input v-model.number="form.circunferencia" type="number" min="0" class="form-control"></div><div class="col-12"><label class="form-label">Evolución *</label><textarea v-model.trim="form.evolucion" class="form-control" rows="5" required placeholder="Describa el estado y evolución del paciente durante el turno"></textarea></div><div class="col-12"><label class="form-label">Observación</label><textarea v-model.trim="form.observacion" class="form-control" rows="3"></textarea></div></div><div class="form-actions"><button type="button" class="btn btn-outline-secondary" :disabled="saving" @click="$emit('cancel')">Cancelar</button><button class="btn btn-primary" :disabled="saving"><span v-if="saving" class="spinner-border spinner-border-sm me-2"></span>{{ saving ? 'Guardando evolución…' : 'Guardar visita de enfermería' }}</button></div></form></template>
<script setup>import { reactive } from 'vue';defineProps({saving:Boolean});const emit=defineEmits(['submit','cancel','dirty']);const localDate=()=>{const d=new Date(),o=d.getTimezoneOffset();return new Date(d.getTime()-o*60000).toISOString().slice(0,16)};const form=reactive({fecha_actividad:localDate(),sv_pa_sistolica:'',sv_pa_diastolica:'',sv_frecuencia_cardiaca:'',sv_frecuencia_respiratoria:'',sv_temperatura:'',saturacion:'',peso:'',sv_talla:'',circunferencia:'',evolucion:'',observacion:''});function submit(){const payload={...form,fecha_actividad:form.fecha_actividad.replace('T',' ')+':00',temp:form.sv_temperatura};emit('submit',payload)}</script>
<style scoped>.form-actions{display:flex;justify-content:flex-end;gap:.7rem;padding-top:1.25rem;margin-top:1.25rem;border-top:1px solid #e8edf2}@media(max-width:575px){.form-actions{flex-direction:column-reverse}.form-actions .btn{width:100%}}</style>
